// Todoist on the person's own API token: every operation of Todoist's API v1. actions.json is generated by
// `bun scripts/openapi-actions.ts todoist`. Todoist's webhooks belong to a registered app, not a personal token, so triggers are polled (polls/todoist.ts).
import { z } from "zod";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";

const api: Api = { name: "Todoist", base: "https://api.todoist.com", tokenHelp: "app.todoist.com/app/settings/integrations/developer" };

export const todoist: OwnApp = {
  app: "todoist",
  name: "Todoist",
  logo: "/logos/todoist.svg",
  keyField: { label: "API token", help: "Todoist → Settings → Integrations → Developer → copy your API token.", placeholder: "0123456789abcdef..." },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/api/v1/user", query: [], headers: [] }, {})) as { full_name?: string; email?: string };
    return me.full_name || me.email;
  },
  actions: {
    ...(await specActions(new URL("./actions.json", import.meta.url), api)),
    // Some things Todoist only does through /sync (reordering, batches), and it isn't in the spec
    sync: rest(
      api,
      "POST",
      "/api/v1/sync",
      "Todoist's batch endpoint: read everything that changed since a sync token, or run several commands at once, including ones with no action of their own (reordering, for example). Each command is {type, uuid, args, temp_id?}.",
      z.object({
        sync_token: z.string().optional().describe('"*" for everything, or the sync_token from the last answer'),
        resource_types: z.array(z.string()).optional().describe('What to read, e.g. ["items", "projects"], or ["all"]'),
        commands: z.array(z.record(z.string(), z.unknown())).optional().describe("Commands to run, see Todoist's Sync API"),
      }),
    ),
  },
};
